contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We'll test buy behavior. Provide tokenIds and tokenWeights arrays, a proof struct
    // and an amount of ETH to forward (amount) when baseToken == address(0).
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofProof,
        bool[] calldata proofFlags,
        uint256 amount
    ) public payable {
        require(tokenIds.length == tokenWeights.length);

        // Build MerkleMultiProof as calldata-compatible struct
        C.MerkleMultiProof memory proof = C.MerkleMultiProof({ proof: new bytes32[](proofProof.length), flags: new bool[](proofFlags.length) });
        for (uint256 i = 0; i < proofProof.length; i++) proof.proof[i] = proofProof[i];
        for (uint256 i = 0; i < proofFlags.length; i++) proof.flags[i] = proofFlags[i];

        // Observe pre-state
        uint256 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint256 beforeVirtualNft = c.virtualNftReserves();
        address baseToken = c.baseToken();
        uint256 poolEthBefore = address(c).balance;

        // Prepare calldata arrays for call
        // We must call c.buy{value: amount}(...)
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // Ensure this contract has enough ETH if sending
        if (baseToken == address(0)) {
            require(address(this).balance >= amount);
        } else {
            // if baseToken != 0, we must not send ETH
            amount = 0;
        }

        // Make the call and capture revert
        try c.buy{value: amount}(tokenIds, tokenWeights, C.MerkleMultiProof({ proof: proof.proof, flags: proof.flags })) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint256 afterVirtualNft = c.virtualNftReserves();
        uint256 poolEthAfter = address(c).balance;

        // General rule (single assert): If buy did NOT revert then
        // 1) the pool's virtualNftReserves decreased by exactly the summed weights (sumWeights)
        //    (i.e., afterVirtualNft + sumWeights == beforeVirtualNft)
        // 2) the pool's virtualBaseTokenReserves increased by at least netInputAmount - feeAmount - protocolFeeAmount (non-decreasing when accounting for fees)
        // 3) For ETH pools (baseToken==0) the contract's ETH balance did not decrease (poolEthAfter >= poolEthBefore)
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) sumWeights += tokenWeights[i];

        // Avoid underflow in the assert by using comparisons and avoiding subtraction that can underflow.
        bool condition;
        if (reverted) {
            // If reverted we do not require anything about state — but must still produce a formula that holds: reverted => true
            condition = reverted;
        } else {
            // Check virtualNft change: beforeVirtualNft == afterVirtualNft + sumWeights
            bool nftChangeOk = (beforeVirtualNft == afterVirtualNft + sumWeights);

            // The expected increment to virtualBaseTokenReserves per contract: + (netInputAmount - feeAmount - protocolFeeAmount)
            // So afterVirtualBase should be >= beforeVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount) OR equal (in case of rounding).
            // To avoid underflow, compute expectedIncrease safely.
            bool baseChangeOk;
            if (netInputAmount >= feeAmount + protocolFeeAmount) {
                uint256 expectedInc = netInputAmount - feeAmount - protocolFeeAmount;
                baseChangeOk = (afterVirtualBase >= beforeVirtualBase + expectedInc);
            } else {
                // unexpected but allow that afterVirtualBase >= beforeVirtualBase (not decreased)
                baseChangeOk = (afterVirtualBase >= beforeVirtualBase);
            }

            bool ethBalanceOk = true;
            if (baseToken == address(0)) {
                ethBalanceOk = (poolEthAfter >= poolEthBefore);
            }

            condition = (!reverted) && nftChangeOk && baseChangeOk && ethBalanceOk;
        }

        assert(condition);
    }

    // Allow contract to receive ETH for testing
    receive() external payable {}
}

