contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We observe that successful buy transfers NFTs from the pool to caller and updates virtualBaseTokenReserves
    // Parameters:
    // - tokenIds and tokenWeights are parallel arrays passed to buy
    // - proofProof and proofFlags form the MerkleMultiProof calldata
    // - payAmount is the Ether amount to forward when baseToken == address(0)
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proofProof, bool[] calldata proofFlags, uint256 payAmount) public payable {
        require(address(this).balance >= payAmount, "insufficient balance for test");

        // Read observable pre-state
        uint256 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNftReserves = c.virtualNftReserves();
        address poolNft = c.nft();
        uint256 beforeNftBalance = 0;
        // balanceOf is view on ERC721
        try ERC721(poolNft).balanceOf(address(c)) returns (uint256 b) {
            beforeNftBalance = b;
        } catch {
            // if call reverts, leave as zero — subsequent assert will account via revert flag
            beforeNftBalance = 0;
        }

        // Prepare MerkleMultiProof struct in memory
        C.MerkleMultiProof memory proof;
        proof.proof = proofProof;
        proof.flags = proofFlags;

        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // Call buy on c. Must be top-level statement.
        try c.buy{value: payAmount}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // Read observable post-state
        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNftReserves = c.virtualNftReserves();
        uint256 afterNftBalance = 0;
        try ERC721(poolNft).balanceOf(address(c)) returns (uint256 b2) {
            afterNftBalance = b2;
        } catch {
            afterNftBalance = 0;
        }

        // General rule (single assert): If the call succeeded then
        // 1) the pool's observable NFT balance decreased by exactly tokenIds.length,
        // 2) virtualNftReserves decreased by the sum of tokenWeights,
        // 3) virtualBaseTokenReserves increased by (netInputAmount - feeAmount - protocolFeeAmount),
        //    which is how the contract computes internal update before royalty adjustments.
        // If the call reverted then nothing is required about balances (we only assert that reverted implies at least
        // one of the observable deltas does not satisfy the success equalities). This combined condition is a general
        // invariant linking success to the expected observable updates.

        // Compute sum of tokenWeights safely (in view — allowed inside assert only values already computed)
        uint256 weightsSum = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            weightsSum += tokenWeights[i];
        }

        // Build the expected relations
        bool nftBalanceDecreasedByCount = (beforeNftBalance >= tokenIds.length) && (beforeNftBalance - tokenIds.length == afterNftBalance);
        bool nftReservesDecreasedByWeights = (beforeVirtualNftReserves >= uint128(weightsSum)) && (beforeVirtualNftReserves - uint128(weightsSum) == afterVirtualNftReserves);
        // net increase in virtualBase equals netInputAmount - fee - protocolFee per implementation
        bool virtualBaseIncreasedAsReported = (afterVirtualBase == beforeVirtualBase + (reverted ? 0 : (netInputAmount - feeAmount - protocolFeeAmount)));

        // If call did not revert then all three must hold. If it reverted then at least one must be false.
        assert((!reverted && nftBalanceDecreasedByCount && nftReservesDecreasedByWeights && virtualBaseIncreasedAsReported) || (reverted && (!(nftBalanceDecreasedByCount && nftReservesDecreasedByWeights && virtualBaseIncreasedAsReported))));
    }

    receive() external payable {}
}

