        try ERC721(poolNft).balanceOf(address(c)) returns (uint256 b) {
            beforeNftBalance = b;
        } catch {
            beforeNftBalance = 0;
        }

        // Prepare MerkleMultiProof struct in memory (must be memory for the external call)
        C.MerkleMultiProof memory proof;
        proof.proof = proofProof;
        proof.flags = proofFlags;

        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // Top-level state-changing call as required by the harness shape
        try c.buy{value: payAmount}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
