        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();
        uint256 afterNftBalance;
        try ERC721(poolNft).balanceOf(address(c)) returns (uint256 b2) {
            afterNftBalance = b2;
        } catch {
            afterNftBalance = 0;
