        // Compute sum of provided weights (allowed in the test function)
        uint256 weightsSum = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            weightsSum += tokenWeights[i];
        }

        // Expected changes if buy succeeded per implementation:
        // virtualNftReserves decreases by weightsSum
        bool nftReservesDecreasedAsExpected = (beforeVirtualNft >= uint128(weightsSum)) && (afterVirtualNft == beforeVirtualNft - uint128(weightsSum));
        // virtualBaseTokenReserves increases by netInputAmount - feeAmount - protocolFeeAmount
